#include "postquantiquecoin/cli/WalletCLI.h"
#include "postquantiquecoin/core/Amount.h"
#include <iostream>
namespace pqc { WalletCLI::WalletCLI(WalletManager& w,Blockchain& b):wm_(w),bc_(b){} int WalletCLI::Execute(const std::vector<std::string>& a){ if(a.empty()){ std::cout<<"commands: create unlock lock newaddress listaddresses balance send backup rescan\n"; return 0; } const auto& c=a[0]; if(c=="create"&&a.size()>1) return WalletCommands::commandCreate(wm_,a[1],a.size()>2?a[2]:"password"); if(c=="unlock"&&a.size()>1) return WalletCommands::commandUnlock(wm_,a[1],a.size()>2?a[2]:"password"); if(c=="lock"&&a.size()>1) return WalletCommands::commandLock(wm_,a[1]); if(c=="newaddress"&&a.size()>2) return WalletCommands::commandNewAddress(wm_,a[1],a[2]); if(c=="listaddresses"&&a.size()>1) return WalletCommands::commandListAddresses(wm_,a[1]); if(c=="balance"&&a.size()>1) return WalletCommands::commandBalance(wm_,a[1],bc_); if(c=="send"&&a.size()>4){ auto amt=Amount::FromCoinsString(a[3]); auto fee=Amount::FromCoinsString(a[4]); if(amt.IsErr()||fee.IsErr()) return 1; return WalletCommands::commandSend(wm_,a[1],a[2],amt.Value(),fee.Value(),bc_); } if(c=="backup"&&a.size()>2) return WalletCommands::commandBackup(wm_,a[1],a[2]); if(c=="rescan"&&a.size()>1) return WalletCommands::commandRescan(wm_,a[1],bc_); std::cout<<"bad wallet command\n"; return 1; } }
